+function Get-TemplateStorePath {
+    param([Parameter(Mandatory)][string]$DataFile)
+
+    return "$DataFile.templates.json"
+}
+
+function Read-TemplateStore {
+    param([Parameter(Mandatory)][string]$Path)
+
+    if (-not (Test-Path -LiteralPath $Path)) {
+        return @()
+    }
+
+    $content = Get-Content -LiteralPath $Path -Raw
+    if ([string]::IsNullOrWhiteSpace($content)) {
+        return @()
+    }
+
+    $parsed = ConvertFrom-Json -InputObject $content
+    return @($parsed)
+}
+
+function Write-TemplateStore {
+    param(
+        [Parameter(Mandatory)][string]$Path,
+        [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Templates
+    )
+
+    $parent = Split-Path -Parent $Path
+    if ($parent -and -not (Test-Path -LiteralPath $parent)) {
+        New-Item -ItemType Directory -Path $parent -Force | Out-Null
+    }
+
+    $temporary = "$Path.$PID.tmp"
+    $json = ConvertTo-Json -InputObject @($Templates) -Depth 8
+    [System.IO.File]::WriteAllText($temporary, "$json`n", [System.Text.UTF8Encoding]::new($false))
+    Move-Item -LiteralPath $temporary -Destination $Path -Force
+}
+
+function Get-ValidTemplateName {
+    param([Parameter(Mandatory)][string]$Name)
+
+    $trimmed = $Name.Trim()
+    if ($trimmed.Length -lt 1 -or $trimmed.Length -gt 64 -or
+        $trimmed -notmatch '^[A-Za-z0-9][A-Za-z0-9 ._-]*$') {
+        throw 'Template names must be 1-64 characters and use only letters, numbers, spaces, periods, underscores, or hyphens.'
+    }
+
+    return $trimmed
+}
